  intents: [
    Intents.FLAGS.GUILDS,
    Intents.FLAGS.GUILD_MEMBERS,
    Intents.FLAGS.GUILD_MESSAGES,
    Intents.FLAGS.GUILD_BANS
  ]
});

client.on('ready', () => {
  console.log(`Bot is ready!`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'You don't have the necessary permissions to use this command.',
        ephemeral: true
      });
    }

    const member = interaction.options.getMember('user');
    if (!member) {
      return interaction.reply({
        content: 'Please provide a valid user to ban.',
        ephemeral: true
      });
    }

    if (member.id === interaction.user.id) {
      return interaction.reply({
        content: 'You cannot ban yourself.',
        ephemeral: true
      });
    }

    await interaction.guild?.members.ban(member, { days: 0, reason: 'Banned by Discord Bot' });
    return interaction.reply({
      content: `${member.user.tag} has been banned.`,
      ephemeral: false
    });
  }
});

client.login(token);
