#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/regex.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Define Markdown syntax patterns
    const boost::regex markdown_bold_pattern(R"(\*\*(.+?)\*\*)");
    const boost::regex markdown_italic_pattern(R"(\*(.+?)\*)");
    const boost::regex markdown_header_pattern(R"(^(#{1,6})\s(.+?))");
    const boost::regex markdown_link_pattern(R"\[(.+?)\]\((.+?)\)");
    const boost::regex markdown_blockquote_pattern(R"^(>.*?$)");

    // Define HTML tags
    const std::string html_bold_tag = "<strong>";
    const std::string html_italic_tag = "<em>";
    const std::string html_header_tag = "<h%d>%s</h%d>";
    const std::string html_link_tag = "<a href=\"%s\">%s</a>";
    const std::string html_blockquote_tag = "<blockquote>";

    std::string html;

    // Replace Markdown syntax with corresponding HTML tags
    boost::replace_all(markdown, "*", html_italic_tag);
    boost::replace_all(markdown, "**", html_bold_tag);
    boost::regex_replace(markdown, markdown_bold_pattern, html_bold_tag + "$1" + html_bold_tag);
    boost::regex_replace(markdown, markdown_italic_pattern, html_italic_tag + "$1" + html_italic_tag);
    boost::regex_replace(markdown, markdown_header_pattern, std::string(html_header_tag) % "$1" % "$2" % "$1");
    boost::regex_replace(markdown, markdown_link_pattern, html_link_tag % "$2" % "$1");
    boost::regex_replace(markdown, markdown_blockquote_pattern, html_blockquote_tag + "$0" + "</blockquote>");

    return html;
}

int main() {
    std::string markdown = "Hello **world**! \n\n This is an *example* of **Markdown**. \n\n # Header 1 \n ## Header 2 \n ### Header 3 \n #### Header 4 \n ##### Header 5 \n ###### Header 6 \n \n [Google](https://www.google.com/) ";

    std::string html = convertMarkdownToHtml(markdown);

    std::cout << "Markdown:\n" << markdown << "\n\n";
    std::cout << "HTML:\n" << html << "\n\n";

    return 0;
}
```

