```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    // Eingabe des Wortes, nach dem gesucht werden soll
    std::string search_word;
    std::cout << "Enter the word to search for: ";
    std::cin >> search_word;

    // Öffnen der Textdatei
    std::ifstream input_file("input_file.txt");

    if (!input_file) {
        std::cerr << "Error: Could not open input file." << std::endl;
        return 1;
    }

    // Variablen für die Wortzähler
    int word_count = 0;

    // Lesen der Datei Zeile für Zeile und Suchen nach dem gesuchten Wort
    std::string line;
    while (getline(input_file, line)) {
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            word_count++;
            pos += search_word.length();
        }
    }

    // Schließen der Datei
    input_file.close();

    // Ausgabe des Wortzählers
    std::cout << "The word \"" << search_word << "\" appears " << word_count << " times in the input file." << std::endl;

    return 0;
}
```

Dieses Programm benötigt folgende Datei "input_file.txt" im selben Verzeichnis, in dem das Programm gespeichert ist:

